mod sortedcontainers;

use sortedcontainers::SortedMap;

fn parse_atoi_like(raw: &str) -> i32 {
    let trimmed = raw.trim_start();
    let bytes = trimmed.as_bytes();
    let mut index = 0usize;
    let mut sign = 1i64;

    if let Some(&byte) = bytes.first() {
        if byte == b'+' {
            index = 1;
        } else if byte == b'-' {
            sign = -1;
            index = 1;
        }
    }

    let mut value = 0i64;
    let mut saw_digit = false;

    while index < bytes.len() {
        let byte = bytes[index];
        if !byte.is_ascii_digit() {
            break;
        }

        saw_digit = true;
        value = value
            .saturating_mul(10)
            .saturating_add(i64::from(byte - b'0'));
        index += 1;
    }

    if !saw_digit {
        return 0;
    }

    let signed = value.saturating_mul(sign);
    signed.clamp(i64::from(i32::MIN), i64::from(i32::MAX)) as i32
}

fn bool_to_i32(value: bool) -> i32 {
    if value { 1 } else { 0 }
}

fn tuple_key(i: i32) -> (i32, i32) {
    (i, i * 2)
}

fn main() {
    let mut n = 18i32;
    if let Some(raw) = std::env::args().nth(1) {
        n = parse_atoi_like(&raw);
    }

    let mut m: SortedMap<(i32, i32), String> = SortedMap::new();
    let mut i = 0i32;
    while i < n {
        m.insert(tuple_key(i), format!("value_{i}"));
        i += 1;
    }

    println!("{}", m.size());

    let test_key1 = (3, 6);
    let test_key2 = (5, 10);

    println!("{}", bool_to_i32(m.contains(&test_key1)));
    println!("{}", bool_to_i32(m.contains(&test_key2)));

    println!("{}", m.get_or_insert_default(test_key1));

    *m.get_or_insert_default_mut(test_key1) = String::from("modified");
    println!("{}", m.get_or_insert_default(test_key1));

    let keys = m.keys();
    let values = m.values();

    println!("{}", keys.len());
    println!("{}", values.len());

    let mut i = 0i32;
    while i < 4 {
        m.erase(&tuple_key(i));
        i += 1;
    }

    println!("{}", m.size());

    if let Some((_, value)) = m.find(&(6, 12)) {
        println!("{value}");
    }

    if let Some((key, _)) = m.lower_bound(&(7, 14)) {
        println!("{}", key.0);
    }

    if let Some((key, _)) = m.upper_bound(&(7, 14)) {
        println!("{}", key.0);
    }

    let mut m2: SortedMap<(i32, i32), String> = SortedMap::new();
    let mut i = 0i32;
    while i < n / 2 {
        let base = i + 10;
        m2.insert(tuple_key(base), format!("other_{i}"));
        i += 1;
    }

    sortedcontainers::update(&mut m, &m2);

    println!("{}", m.size());
    println!("{}", bool_to_i32(m.contains(&(12, 24))));

    let count = m.equal_range(&(8, 16)).count();
    println!("{count}");

    println!("{}", m.get(&(100, 200), String::from("default")));

    m.clear();

    println!("{}", m.size());
    println!("{}", bool_to_i32(m.empty()));
}

